code.javascript:
function countdown(n) {
  if (n === 0) {
    console.log("Done");
    return;
  }
  console.log(n);
  countdown(n - 1);
}
countdown(3);

code.cpp:
!#include <iostream>
using namespace std;

void countdown(int n) {
    if (n == 0) {
        cout << "Done" << endl;
        return;
    }
    cout << n << endl;
    countdown(n - 1);
}

int main() {
    countdown(3);
    return 0;
}

code.csharp:
